ace(NULLIF(BTRIM("cac_ref"::text), ''), ',', '.')::numeric ELSE NULL END) IS NOT NULL AND (CASE WHEN "aloj"::text NOT IN ('NaN','Infinity','-Infinity') THEN "aloj"::numeric ELSE NULL END) IS NOT NULL THEN (CASE WHEN "aloj"::text NOT IN ('NaN','Infinity','-Infinity') THEN "aloj"::numeric ELSE NULL END) END), 0) AS "cac_ref", SUM(CASE WHEN "qt_aves"::text NOT IN ('NaN','Infinity','-Infinity') THEN "qt_aves"::numeric ELSE NULL END) AS "aves_abatidas" FROM contexto WHERE EXTRACT(month FROM "data_abate"::date)::integer IS NOT NULL GROUP BY 1,2 UNION ALL SELECT EXTRACT(year FROM "data_abate"::date)::integer AS ano, NULL AS mes_numero, ((SUM(CASE WHEN "pes_total"::text NOT IN ('NaN','Infinity','-Infinity') THEN "pes_total"::numeric ELSE NULL END) / NULLIF(SUM((CASE WHEN "qt_aves"::text NOT IN ('NaN','Infinity','-Infinity') THEN "qt_aves"::numeric ELSE NULL END) * (CASE WHEN "ida"::text NOT IN ('NaN','Infinity','-Infinity') THEN "ida"::numeric ELSE NULL END)), 0) * 1000) / 1000) * (100 - (SUM(CASE WHEN "_mt_registro_incluido" THEN (CASE WHEN "mort"::text NOT IN ('NaN','Infinity','-Infinity') THEN "mort"::numeric ELSE NULL END) END) / NULLIF(SUM(CASE WHEN "_mt_registro_incluido" THEN (CASE WHEN "aloj"::text NOT IN ('NaN','Infinity','-Infinity') THEN "aloj"::numeric ELSE NULL END) END), 0) * 100)) / NULLIF((SUM(CASE WHEN "consumo_racao"::text NOT IN ('NaN','Infinity','-Infinity') THEN "consumo_racao"::numeric ELSE NULL END) / NULLIF(SUM(CASE WHEN "pes_total"::text NOT IN ('NaN','Infinity','-Infinity') THEN "pes_total"::numeric ELSE NULL END), 0) * 1),0) * 100 AS "iep", SUM(CASE WHEN "consumo_racao"::text NOT IN ('NaN','Infinity','-Infinity') THEN "consumo_racao"::numeric ELSE NULL END) / NULLIF(SUM(CASE WHEN "pes_total"::text NOT IN ('NaN','Infinity','-Infinity') THEN "pes_total"::numeric ELSE NULL END), 0) * 1 AS "ca", SUM((CASE WHEN "cac"::text NOT IN ('NaN','Infinity','-Infinity') THEN "cac"::numeric ELSE NULL END) * (CASE WHEN "aloj"::text NOT IN ('NaN','Infinity','-Infin