CTICIO__' THEN 'diagnostico' ELSE NULL::text END) AS za_owner FROM "zootecnico"."base_dinamica" p), "za_conflicts_base_dinamica" AS (SELECT "k0", "k1", "k2", "k3" FROM "za_versions_base_dinamica" GROUP BY "k0", "k1", "k2", "k3" HAVING BOOL_OR(za_owner IS NULL) OR COUNT(DISTINCT za_owner)>1), "za_scope_base_dinamica" AS (SELECT s.* FROM "zootecnico"."base_dinamica" s WHERE (CASE NULLIF(BTRIM(to_jsonb("s")->>'tecnico'),'') WHEN '__DIAGNOSTICO_FICTICIO__' THEN 'diagnostico' ELSE NULL::text END) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "za_conflicts_base_dinamica" p WHERE NULLIF(BTRIM("s"."cod_prod"::text),'') = p."k0" AND NULLIF(BTRIM("s"."galpao"::text),'') = p."k1" AND NULLIF(BTRIM("s"."lote"::text),'') = p."k2" AND (SELECT CASE WHEN NULLIF(BTRIM("za_day"::text), '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}([ T].*)?$' THEN CASE WHEN substring(NULLIF(BTRIM("za_day"::text), '') from 1 for 4)::integer BETWEEN 1 AND 9999 AND substring(NULLIF(BTRIM("za_day"::text), '') from 6 for 2)::integer BETWEEN 1 AND 12 THEN CASE WHEN substring(NULLIF(BTRIM("za_day"::text), '') from 9 for 2)::integer BETWEEN 1 AND EXTRACT(day FROM (make_date(substring(NULLIF(BTRIM("za_day"::text), '') from 1 for 4)::integer,substring(NULLIF(BTRIM("za_day"::text), '') from 6 for 2)::integer,1) + interval '1 month - 1 day')) THEN make_date(substring(NULLIF(BTRIM("za_day"::text), '') from 1 for 4)::integer,substring(NULLIF(BTRIM("za_day"::text), '') from 6 for 2)::integer,substring(NULLIF(BTRIM("za_day"::text), '') from 9 for 2)::integer) ELSE NULL END ELSE NULL END WHEN NULLIF(BTRIM("za_day"::text), '') ~ '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN CASE WHEN substring(NULLIF(BTRIM("za_day"::text), '') from 7 for 4)::integer BETWEEN 1 AND 9999 AND substring(NULLIF(BTRIM("za_day"::text), '') from 4 for 2)::integer BETWEEN 1 AND 12 THEN CASE WHEN substring(NULLIF(BTRIM("za_day"::text), '') from 1 for 2)::integer BETWEEN 1 AND EXTRACT(day FROM (make_date(substring(NULLIF(BTRIM("za_day"::text), '') from 7 for 4)::integer,substring(NULLIF(BTRIM("za_day"::text), '') from 4 for 2)::integer,1) + interval '1 month - 1 day')) THEN make_date(substring(NULLIF(BTRIM("za_day"::text), '') from 7 for 4)::integer,substring(NULLIF(BTRIM("za_day"::text), '') from 4 for 2)::integer,substring(NULLIF(BTRIM("za_day"::text), '') from 1 for 2)::integer) ELSE NULL END ELSE NULL END ELSE NULL END FROM (SELECT "s"."data_de_alojamento" AS za_day) za_date) = p."k3")), "za_versions_vw_desempenho_acerto_portal" AS MATERIALIZED (SELECT NULLIF(BTRIM("p".chave_lote::text),'') AS "k0", (CASE NULLIF(BTRIM(to_jsonb("p")->>'tecnico'),'') WHEN '__DIAGNOSTICO_FICTICIO__' THEN 'diagnostico' ELSE NULL::text END) AS za_owner FROM "zootecnico"."vw_desempenho_acerto_portal" p), "za_conflicts_vw_desempenho_acerto_portal" AS (SELECT "k0" FROM "za_versions_vw_desempenho_acerto_portal" GROUP BY "k0" HAVING BOOL_OR(za_owner IS NULL) OR COUNT(DISTINCT za_owner)>1), "za_scope_vw_desempenho_acerto_portal" AS (SELECT s.* FROM "zootecnico"."vw_desempenho_acerto_portal" s WHERE (CASE NULLIF(BTRIM(to_jsonb("s")->>'tecnico'),'') WHEN '__DIAGNOSTICO_FICTICIO__' THEN 'diagnostico' ELSE NULL::text END) IS NOT NULL AND COALESCE(to_jsonb(s)->>'candidatos_tecnico','1') !~ '^(?:[2-9]|[1-9][0-9]+)$' AND (NULLIF(BTRIM(to_jsonb(s)->>'tecnico_exibicao'),'') IS NULL OR (CASE NULLIF(BTRIM(to_jsonb("s")->>'tecnico'),'') WHEN '__DIAGNOSTICO_FICTICIO__' THEN 'diagnostico' ELSE NULL::text END) = (CASE BTRIM(to_jsonb(s)->>'tecnico_exibicao') WHEN '__DIAGNOSTICO_FICTICIO__' THEN 'diagnostico' ELSE NULL::text END)) AND NOT EXISTS (SELECT 1 FROM "za_conflicts_vw_desempenho_acerto_portal" p WHERE NULLIF(BTRIM("s".chave_lote::text),'') = p."k0")), "detalhes_contexto_principal" AS MATERIALIZED (SELECT * FROM (WITH mt_official AS MATERIALIZED (SELECT * FROM "za_scope_vw_desempenho_acerto_portal" WHERE EXTRACT(year FROM "data_abate"::date)::integer >= 2023 AND EXTRACT(month FROM "data_abate"::date)::integer IS NOT NULL AND EXTRACT(year FROM "data_abate"::date)::integer IN (2026)), mt_wanted AS MATERIALIZED (SELECT DISTINCT NULLIF(BTRIM(o.codigo::text),'') AS kc, NULLIF(BTRIM(o.gal::text),'') AS kg, NULLIF(BTRIM(o.lote::text),'') AS kl, (SELECT CASE WHEN NULLIF(BTRIM("mt_aloj"::text), '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}([ T].*)?$' THEN CASE WHEN substring(NULLIF(BTRIM("mt_aloj"::text), '') from 1 for 4)::integer BETWEEN 1 AND 9999 AND substring(NULLIF(BTRIM("mt_aloj"::text), '') from 6 for 2)::integer BETWEEN 1 AND 12 THEN CASE WHEN substring(NULLIF(BTRIM("mt_aloj"::text), '') from 9 for 2)::integer BETWEEN 1 AND EXTRACT(day FROM (make_date(substring(NULLIF(BTRIM("mt_aloj"::text), '') from 1 for 4)::integer,substring(NULLIF(BTRIM("mt_aloj"::text), '') from 6 for 2)::integer,1) + interval '1 month - 1 day')) THEN make_date(substring(NULLIF(BTRIM("mt_aloj"::text), '') from 1 for 4)::integer,substring(NULLIF(BTRIM("mt_aloj"::text), '') from 6 for 2)::integer,substring(NULLIF(BTRIM("mt_aloj"::text), '') from 9 for 2)::integer) ELSE NULL END ELSE NULL END WHEN NULLIF(BTRIM("mt_aloj"::text), '') ~ '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN CASE WHEN substring(NULLIF(BTRIM("mt_aloj"::text), '') from 7 for 4)::integer BETWEEN 1 AND 9999 AND substring(NULLIF(BTRIM("mt_aloj"::text), '') from 4 for 2)::integer BETWEEN 1 AND 12 THEN CASE WHEN substring(NULLIF(BTRIM("mt_aloj"::text), '') from 1 for 2)::integer BETWEEN 1 AND EXTRACT(day FROM (make_date(substring(NULLIF(BTRIM("mt_aloj"::text), '') from 7 for 4)::integer,substring(NULLIF(BTRIM("mt_aloj"::text), '') from 4 for 2)::integer,1) + interval '1 month - 1 day')) THEN make_date(substring(NULLIF(BTRIM("mt_aloj"::text), '') from 7 for 4)::integer,substring(NULLIF(BTRIM("mt_aloj"::text), '') from 4 for 2)::integer,substring(NULLIF(BTRIM("mt_aloj"::text), '') from 1 for 2)::integer) ELSE NULL END ELSE NULL END ELSE NULL END FROM (SELECT "o"."dt_aloj" AS mt_aloj) q) AS kd FROM mt_official o), mt_latest AS MATERIALIZED (SELECT DISTINCT ON (c.kc,c.kg,c.kl,c.kd) c.kc,c.kg,c.kl,c.kd,c.valid FROM (SELECT NULLIF(BTRIM("cod_prod"::text), '') AS kc, NULLIF(BTRIM("galpao"::text), '') AS kg, NULLIF(BTRIM("lote"::text), '') AS kl, CASE WHEN NULLIF(BTRIM("data_de_alojamento"::text), '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}([ T].*)?$' THEN CASE WHEN substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 1 for 4)::integer BETWEEN 1 AND 9999 AND substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 6 for 2)::integer BETWEEN 1 AND 12 THEN CASE WHEN substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 9 for 2)::integer BETWEEN 1 AND EXTRACT(day FROM (make_date(substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 1 for 4)::integer,substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 6 for 2)::integer,1) + interval '1 month - 1 day')) THEN make_date(substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 1 for 4)::integer,substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 6 for 2)::integer,substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 9 for 2)::integer) ELSE NULL END ELSE NULL END WHEN NULLIF(BTRIM("data_de_alojamento"::text), '') ~ '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN CASE WHEN substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 7 for 4)::integer BETWEEN 1 AND 9999 AND substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 4 for 2)::integer BETWEEN 1 AND 12 THEN CASE WHEN substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 1 for 2)::integer BETWEEN 1 AND EXTRACT(day FROM (make_date(substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 7 for 4)::integer,substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 4 for 2)::integer,1) + interval '1 month - 1 day')) THEN make_date(substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 7 for 4)::integer,substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 4 for 2)::integer,substring(NULLIF(BTRIM("data_de_alojamento"::text), '') from 1 for 2)::integer) ELSE NULL END ELSE NULL END ELSE NULL END AS kd, COALESCE(CASE WHEN NULLIF(BTRIM("mortalidade"::text), '') ~ '^[+-]?[0-9]+([.,][0-9]+)?$' THEN replace(NULLIF(BTRIM("mortalidade"::text), ''), ',', '.')::numeric ELSE NULL END >= 0, TRUE) AND COALESCE(CASE WHEN NULLIF(BTRIM("m_sem_1"::text), '') ~ '^[+-]?[0-9]+([.,][0-9]+)?$' THEN replace(NULLIF(BTRIM("m_sem_1"::text), ''), ',', '.')::numeric ELSE NULL END >= 0, TRUE) AND COALESCE(CASE WHEN NULLIF(BTRIM("d_sem_1"::text), '') ~ '^[+-]?[0-9]+([.,][0-9]+)?$' THEN replace(NULLIF(BTRIM("d_sem_1"::text), ''), ',', '.')::numeric ELSE NULL END >= 0, TRUE) AND COALESCE(CASE WHEN NULLIF(BTRIM("m_sem_2"::text), '') ~ '^[+-]?[0-9]+([.,][0-9]+)?$' THEN replace(NULLIF(BTRIM("m_sem_2"::text), ''), ',', '.')::numeric ELSE NULL END >= 0, TRUE) AND COALESCE(CASE WHEN NULLIF(BTRIM("d_sem_2"::text), '') ~ '^[+-]?[0-9]+([.,][0-9]+)?$' THEN replace(NULLIF(BTRIM("d_sem_2"::text), ''), ',', '.')::numeric ELSE NULL END >= 0, TRUE) AND COALESCE(CASE WHEN NULLIF(BTRIM("m_sem_3"::text), '') ~ '^[+-]?[0-9]+([.,][0-9]+)?$' THEN replace(NULLIF(BTRIM("m_sem_3"::text), ''), ',', '.')::numeric ELSE NULL END >= 0, TRUE) AND COALESCE(CASE WHEN NULLIF(BTRIM("d_sem_3"::text), '') ~ '^[+-]?[0-9]+([.,][0-9]+)?$' THEN replace(NULLIF(BTRIM("d_sem_3"::text), ''), ',', '.')::numeric ELSE NULL END >= 0, TRUE) AND COALESCE(CASE WHEN NULLIF(BTRIM("m_sem_4"::text), '') ~ '^[+-]?[0-9]+([.,][0-9]+)?$' THEN replace(NULLIF(BTRIM("m_sem_4"::text), ''), ',', '.')::numeric ELSE NULL END >= 0, TRUE) AND COALESCE(CASE WHEN NULLIF(BTRIM("d_sem_4"::text), '') ~ '^[+-]?[0-9]+([.,][0-9]+)?$' THEN replace(NULLIF(BTRIM("d_sem_4"::text), ''), ',', '.')::numeric ELSE NULL END >= 0, TRUE) AND COALESCE(CASE WHEN NULLIF(BTRIM("m_sem_5"::text), '') ~ '^[+-]?[0-9]+([.,][0-9]+)?$' THEN replace(NULLIF(BTRIM("m_sem_5"::text), ''), ',', '.')::numeric ELSE NULL END >= 0, TRUE) AND COALESCE(CASE WHEN NULLIF(BTRIM("d_sem_5"::text), '') ~ '^[+-]?[0-9]+([.,][0-9]+)?$' THEN replace(NULLIF(BTRIM("d_sem_5"::text), ''), ',', '.')::numeric ELSE NULL END >= 0, TRUE) AS valid, CASE WHEN NULLIF(BTRIM("periodo_fim"::text), '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}([ T].*)?$' THEN CASE WHEN substring(NULLIF(BTRIM("periodo_fim"::text), '') from 1 for 4)::integer BETWEEN 1 AND 9999 AND substring(NULLIF(BTRIM("periodo_fim"::text), '') from 6 for 2)::integer BETWEEN 1 AND 12 THEN CASE WHEN substring(NULLIF(BTRIM("periodo_fim"::text), '') from 9 for 2)::integer BETWEEN 1 AND EXTRACT(day FROM (make_date(substring(NULLIF(BTRIM("periodo_fim"::text), '') from 1 for 4)::integer,substring(NULLIF(BTRIM("periodo_fim"::text), '') from 6 for 2)::integer,1) + interval '1 month - 1 day')) THEN make_date(substring(NULLIF(BTRIM("periodo_fim"::text), '') from 1 for 4)::integer,substring(NULLIF(BTRIM("periodo_fim"::text), '') from 6 for 2)::integer,substring(NULLIF(BTRIM("periodo_fim"::text), '') from 9 for 2)::integer) ELSE NULL END ELSE NULL END WHEN NULLIF(BTRIM("periodo_fim"::text), '') ~ '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN CASE WHEN substring(NULLIF(BTRIM("periodo_fim"::text), '') from 7 for 4)::integer BETWEEN 1 AND 9999 AND substring(NULLIF(BTRIM("periodo_fim"::text), '') from 4 for 2)::integer BETWEEN 1 AND 12 THEN CASE WHEN substring(NULLIF(BTRIM("periodo_fim"::text), '') from 1 for 2)::integer BETWEEN 1 AND EXTRACT(day FROM (make_date(substring(NULLIF(BTRIM("periodo_fim"::text), '') from 7 for 4)::integer,substring(NULLIF(BTRIM("periodo_fim"::text), '') from 4 for 2)::integer,1) + interval '1 month - 1 day')) THEN make_date(substring(NULLIF(BTRIM("periodo_fim"::text), '') from 7 for 4)::integer,substring(NULLIF(BTRIM("periodo_fim"::text), '') from 4 for 2)::integer,substring(NULLIF(BTRIM("periodo_fim"::text), '') from 1 for 2)::integer) ELSE NULL END ELSE NULL END ELSE NULL END AS pr, NULLIF(BTRIM("carregado_em"::text), '') AS lr, CASE WHEN NULLIF(BTRIM("id"::text), '') ~ '^[+-]?[0-9]+([.,][0-9]+)?$' THEN replace(NULLIF(BTRIM("id"::text), ''), ',', '.')::numeric ELSE NULL END AS ir FROM "za_scope_base_dinamica" WHERE NULLIF(BTRIM("cod_prod"::text), '') IN (SELECT kc FROM mt_wanted)) c JOIN mt_wanted w ON (c.kc,c.kg,c.kl,c.kd)=(w.kc,w.kg,w.kl,w.kd) ORDER BY c.kc,c.kg,c.kl,c.kd,c.pr DESC NULLS LAST,c.lr DESC NULLS LAST,c.ir DESC NULLS LAST) SELECT o.*, (COALESCE(CASE WHEN o.mort::text NOT IN ('NaN','Infinity','-Infinity') THEN o.mort::numeric END >= 0, TRUE) AND COALESCE(d.valid, TRUE)) AS "_mt_registro_incluido" FROM mt_official o LEFT JOIN mt_latest d ON "d"."kc" = NULLIF(BTRIM("o"."codigo"::text), '') AND "d"."kg" = NULLIF(BTRIM("o"."gal"::text), '') AND "d"."kl" = NULLIF(BTRIM("o"."lote"::text), '') AND d.kd = (SELECT CASE WHEN NULLIF(BTRIM("mt_aloj"::text), '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}([ T].*)?$' THEN CASE WHEN substring(NULLIF(BTRIM("mt_aloj"::text), '') from 1 for 4)::integer BETWEEN 1 AND 9999 AND substring(NULLIF(BTRIM("mt_aloj"::text), '') from 6 for 2)::integer BETWEEN 1 AND 12 THEN CASE WHEN substring(NULLIF(BTRIM("mt_aloj"::text), '') from 9 for 2)::integer BETWEEN 1 AND EXTRACT(day FROM (make_date(substring(NULLIF(BTRIM("mt_aloj"::text), '') from 1 for 4)::integer,substring(NULLIF(BTRIM("mt_aloj"::text), '') from 6 for 2)::integer,1) + interval '1 month - 1 day')) THEN make_date(substring(NULLIF(BTRIM("mt_aloj"::text), '') from 1 for 4)::integer,substring(NULLIF(BTRIM("mt_aloj"::text), '') from 6 for 2)::integer,substring(NULLIF(BTRIM("mt_aloj"::text), '') from 9 for 2)::integer) ELSE NULL END ELSE NULL END WHEN NULLIF(BTRIM("mt_aloj"::text), '') ~ '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN CASE WHEN substring(NULLIF(BTRIM("mt_aloj"::text), '') from 7 for 4)::integer BETWEEN 1 AND 9999 AND substring(NULLIF(BTRIM("mt_aloj"::text), '') from 4 for 2)::integer BETWEEN 1 AND 12 THEN CASE WHEN substring(NULLIF(BTRIM("mt_aloj"::text), '') from 1 for 2)::integer BETWEEN 1 AND EXTRACT(day FROM (make_date(substring(NULLIF(BTRIM("mt_aloj"::text), '') from 7 for 4)::integer,substring(NULLIF(BTRIM("mt_aloj"::text), '') from 4 for 2)::integer,1) + interval '1 month - 1 day')) THEN make_date(substring(NULLIF(BTRIM("mt_aloj"::text), '') from 7 for 4)::integer,substring(NULLIF(BTRIM("mt_aloj"::text), '') from 4 for 2)::integer,substring(NULLIF(BTRIM("mt_aloj"::text), '') from 1 for 2)::integer) ELSE NULL END ELSE NULL END ELSE NULL END FROM (SELECT "o"."dt_aloj" AS mt_aloj) q)) AS mt_contexto WHERE EXTRACT(year FROM "data_abate"::date)::integer >= 2023 AND EXTRACT(month FROM "data_abate"::date)::integer IS NOT NULL AND EXTRACT(year FROM "data_abate"::date)::integer IN (2026)) SELECT 'kpi' AS parte, to_jsonb(k) AS dados, 0::bigint AS ordem FROM (SELECT SUM(CASE WHEN "_mt_registro_incluido" THEN (CASE WHEN "mort"::text NOT IN ('NaN','Infinity','-Infinity') THEN "mort"::numeric ELSE NULL END) END) / NULLIF(SUM(CASE WHEN "_mt_registro_incluido" THEN (CASE WHEN "aloj"::text NOT IN ('NaN','Infinity','-Infinity') THEN "aloj"::numeric ELSE NULL END) END), 0) * 100 AS valor FROM "detalhes_contexto_principal") k UNION ALL SELECT 'tecnicos',to_jsonb(t),row_number() OVER(ORDER BY t.valor DESC NULLS LAST,t.nome) FROM (WITH grupos AS (SELECT COALESCE(NULLIF(BTRIM("tecnico_exibicao"::text), ''), 'Sem técnico') AS nome, NULLIF(BTRIM("tecnico_exibicao"::text), '') IS NULL AS sem_identificacao, SUM(CASE WHEN "_mt_registro_incluido" THEN (CASE WHEN "mort"::text NOT IN ('NaN','Infinity','-Infinity') THEN "mort"::numeric ELSE NULL END) END) / NULLIF(SUM(CASE WHEN "_mt_registro_incluido" THEN (CASE WHEN "aloj"::text NOT IN ('NaN','Infinity','-Infinity') THEN "aloj"::numeric ELSE NULL END) END), 0) * 100 AS valor, COUNT(*) FILTER (WHERE "_mt_registro_incluido") AS lotes, SUM(CASE WHEN "_mt_registro_incluido" THEN (CASE WHEN "mort"::text NOT IN ('NaN','Infinity','-Infinity') THEN "mort"::numeric ELSE NULL END) END) * 100 AS base_numerador, SUM(CASE WHEN "_mt_registro_incluido" THEN (CASE WHEN "aloj"::text NOT IN ('NaN','Infinity','-Infinity') THEN "aloj"::numeric ELSE NULL END) END) AS base_denominador FROM "detalhes_contexto_principal" WHERE EXTRACT(year FROM "data_abate"::date)::integer >= 2023 AND EXTRACT(month FROM "data_abate"::date)::integer IS NOT NULL AND EXTRACT(year FROM "data_abate"::date)::integer IN (2026) GROUP BY 1,2) SELECT *, (SELECT SUM(base_numerador) / NULLIF(SUM(base_denominador),0) FROM grupos) AS valor_recomposto FROM grupos ORDER BY valor DESC NULLS LAST, nome) t UNION ALL SELECT 'produtores',to_jsonb(p),row_number() OVER(ORDER BY p.valor DESC NULLS LAST,p.nome) FROM (WITH grupos AS (SELECT COALESCE(NULLIF(BTRIM("integrado"::text), ''), 'Sem produtor') AS nome, NULLIF(BTRIM("integrado"::text), '') IS NULL AS sem_identificacao, SUM(CASE WHEN "_mt_registro_incluido" THEN (CASE WHEN "mort"::text NOT IN ('NaN','Infinity','-Infinity') THEN "mort"::numeric ELSE NULL END) END) / NULLIF(SUM(CASE WHEN "_mt_registro_incluido" THEN (CASE WHEN "aloj"::text NOT IN ('NaN','Infinity','-Infinity') THEN "aloj"::numeric ELSE NULL END) END), 0) * 100 AS valor, COUNT(*) FILTER (WHERE "_mt_registro_incluido") AS lotes, SUM(CASE WHEN "_mt_registro_incluido" THEN (CASE WHEN "mort"::text NOT IN ('NaN','Infinity','-Infinity') THEN "mort"::numeric ELSE NULL END) END) * 100 AS base_numerador, SUM(CASE WHEN "_mt_registro_incluido" THEN (CASE WHEN "aloj"::text NOT IN ('NaN','Infinity','-Infinity') THEN "aloj"::numeric ELSE NULL END) END) AS base_denominador FROM "detalhes_contexto_principal" WHERE EXTRACT(year FROM "data_abate"::date)::integer >= 2023 AND EXTRACT(month FROM "data_abate"::date)::integer IS NOT NULL AND EXTRACT(year FROM "data_abate"::date)::integer IN (2026) GROUP BY 1,2) SELECT *, (SELECT SUM(base_numerador) / NULLIF(SUM(base_denominador),0) FROM grupos) AS valor_recomposto FROM grupos ORDER BY valor DESC NULLS LAST, nome) p ORDER BY parte,ordem;
ROLLBACK;

-- zootecnico/detalhes [["ano", "2026"], ["indicador", "mortalidade"], ["etapa", "evolucao"], ["agrupamento", "mensal"]]
BEGIN READ ONLY;
